mapper.select:
SELECT d.id as dept_id, d.parent_id, d.ancestors, d.dept_name, d.dept_code, d.order_num, d.leader, d.phone, d.email, d.status, d.is_system, d.remark, d.create_time, d.update_time, d.create_by, d.update_by, d.is_deleted, d.delete_time FROM sys_dept d WHERE d.is_deleted = 0
AND d.dept_name LIKE CONCAT('%', #{deptName}, '%')
AND d.dept_code LIKE CONCAT('%', #{deptCode}, '%')
AND d.status = #{status}
AND d.parent_id = #{parentId}
ORDER BY d.parent_id ASC, d.order_num ASC
